processor-info.script:

            String cmd = input.getText("cmd");  

            String ins_emp_info_yn = input.getText( "ins_emp_info_yn" );
            DataSet day_input = new DataSet();
         	DataSet day_output = new DataSet();
         	DataSet term_output = new DataSet();


            if( "doGlobalEventAdd".equals( cmd ) )
            {
            	executeSQL(cmd, connection, input, output);

            	int seq_no = input.getInt( "seq_no" );
                if( seq_no <= 0 )
                {
	                executeSQL("getGlobalEventsSeqno", connection, input,output);
                }else{
                    output.put("seq_no", seq_no );
                }

            }else if("doGlobalEventDel".equals(cmd))
           	{
           		int deleteNum = 0;
           		executeSQL(cmd, connection, input, output);
				try
				{
					deleteNum = Integer.parseInt(output.getProperty("rowcount.update:doGlobalEventDel"));
				} catch(Exception ex)
				{
				}

				if(deleteNum == 0)
					throw new jdf.framework.core.data.ResourceException("", 20406);
           	} else
           	{
           		executeSQL(cmd, connection, input, output);
           	}
